cards=[]
counts={}
for topic, question, answer in examples:
    counts[topic]=counts.get(topic,0)+1
    support, sources=supports[topic]
    cards.append({'id': f'facies_positive_{topic}_{counts[topic]:02d}', 'topic': topic, 'question': question, 'answer': answer, 'support_text': support, 'source_ids': sources, 'split':'train', 'source_checked':True, 'geologist_reviewed':False})
assert len(cards)==20 and len({c['id'] for c in cards})==20
assert all(20 <= len(c['answer'].split()) <= 45 for c in cards)
payload=(json.dumps({'cards':cards}, ensure_ascii=False, indent=2)+'\n').encode('utf-8')
dest.write_bytes(payload)
print('sha256',hashlib.sha256(payload).hexdigest())
print('topics',counts,'answer min/max',min(len(c['answer'].split()) for c in cards),max(len(c['answer'].split()) for c in cards),'support max',max(len(c['support_text'].split()) for c in cards))
